CREATE TABLE stg_cidadao ASSELECT  CAST(co_fat_cidadao_pec AS INTEGER) co_fat_cidadao_pec,  TRIM(no_cidadao) no_cidadao,  dt_registro_nascimento,  ds_sexo,  nu_cns,  nu_cpf_cidadao,  nu_telefone_celular,  CAST(st_faleceu AS INTEGER) st_faleceu,  dt_ultima_atualizacao_cidadao,  CAST(st_diabetes_diagnosticada AS INTEGER) st_diabetes_diagnosticada,  CAST(st_hipertensao_diagnosticada AS INTEGER) st_hipertensao_diagnosticada,  TRIM(nu_ine) nu_ine,  TRIM(UPPER(REPLACE(REPLACE(no_equipe, '  ', ' '), '  ', ' '))) no_equipe,  data_ultimo_atend_individual,  TRIM(equipe_ine_atendimento) equipe_ine_atendimento,  TRIM(UPPER(REPLACE(REPLACE(equipe_nome_atendimento, '  ', ' '), '  ', ' '))) equipe_nome_atendimento,  nu_atend_ubs_ultimos_12_meses,  data_transmissaoFROM raw_cidadao_pecWHERE co_fat_cidadao_pec <> '';WITH ranked AS (  SELECT    *,    ROW_NUMBER() OVER (PARTITION BY co_seq_fat_atd_ind ORDER BY data_transmissao DESC, rowid ASC) rn  FROM raw_atendimento_individual  WHERE co_seq_fat_atd_ind <> '')CREATE TABLE stg_atendimento_full ASSELECT  co_seq_fat_atd_ind,  CAST(co_fat_cidadao_pec AS INTEGER) co_fat_cidadao_pec,  atend_ind_classificacao,  nu_ciap,  no_ciap,  nu_cid,  no_cid,  TRIM(no_profissional) no_profissional,  SUBSTR(TRIM(nu_cbo), 1, 4) familia_cbo,  nu_cbo,  no_cbo,  ds_local_atendimento,  TRIM(nu_ine) nu_ine,  TRIM(UPPER(REPLACE(REPLACE(no_equipe, '  ', ' '), '  ', ' '))) no_equipe,  dt_registro,  data_transmissao,  propriedades,  versaoFROM rankedWHERE rn = 1;CREATE TABLE stg_atendimento ASSELECT *FROM stg_atendimento_fullWHERE dt_registro <= (SELECT data_referencia FROM param LIMIT 1)  AND dt_registro <> '';CREATE TABLE quarentena_atendimento_datas_futuras ASSELECT  'datas_futuras' motivo,  co_seq_fat_atd_ind,  co_fat_cidadao_pec,  dt_registro,  data_transmissao,  COUNT(*) OVER (PARTITION BY co_seq_fat_atd_ind) reenviosFROM stg_atendimento_fullWHERE dt_registro > (SELECT data_referencia FROM param LIMIT 1)   OR dt_registro = '';WITH ranked AS (  SELECT    *,    ROW_NUMBER() OVER (PARTITION BY co_seq_fat_proced ORDER BY data_transmissao DESC, rowid ASC) rn  FROM raw_procedimentos  WHERE co_seq_fat_proced <> '')CREATE TABLE stg_procedimentos_full ASSELECT  co_seq_fat_proced,  tabela,  CAST(co_fat_cidadao_pec AS INTEGER) co_fat_cidadao_pec,  co_proced,  ds_proced,  SUBSTR(TRIM(nu_cbo), 1, 4) familia_cbo,  nu_cbo,  no_cbo,  TRIM(nu_ine) nu_ine,  TRIM(UPPER(REPLACE(REPLACE(no_equipe, '  ', ' '), '  ', ' '))) no_equipe,  TRIM(no_profissional) no_profissional,  dt_registro,  data_transmissao,  propriedades,  -- Parse JSON: peso e altura  CASE    WHEN ds_proced LIKE '%PESO%'    THEN CAST(JSON_EXTRACT(propriedades, '$.peso') AS REAL)    ELSE NULL  END peso,  CASE    WHEN ds_proced LIKE '%PESO%'    THEN CAST(JSON_EXTRACT(propriedades, '$.altura') AS REAL)    ELSE NULL  END altura,  -- Parse JSON: pressão arterial  JSON_EXTRACT(propriedades, '$.pressao_arterial') pa_strFROM rankedWHERE rn = 1;CREATE TABLE stg_procedimentos ASSELECT  co_seq_fat_proced,  tabela,  co_fat_cidadao_pec,  co_proced,  ds_proced,  familia_cbo,  nu_cbo,  no_cbo,  nu_ine,  no_equipe,  no_profissional,  dt_registro,  data_transmissao,  propriedades,  peso,  altura,  pa_str,  -- Parse sistólica / diastólica  CASE    WHEN pa_str GLOB '[0-9]*/[0-9]*'    THEN CAST(SUBSTR(pa_str, 1, INSTR(pa_str, '/') - 1) AS INTEGER)    ELSE NULL  END pa_sistolica,  CASE    WHEN pa_str GLOB '[0-9]*/[0-9]*'    THEN CAST(SUBSTR(pa_str, INSTR(pa_str, '/') + 1) AS INTEGER)    ELSE NULL  END pa_diastolicaFROM stg_procedimentos_fullWHERE dt_registro <= (SELECT data_referencia FROM param LIMIT 1)  AND dt_registro <> '';CREATE TABLE quarentena_procedimentos_datas_futuras ASSELECT  'datas_futuras' motivo,  co_seq_fat_proced,  co_fat_cidadao_pec,  dt_registro,  data_transmissaoFROM stg_procedimentos_fullWHERE dt_registro > (SELECT data_referencia FROM param LIMIT 1)   OR dt_registro = '';CREATE INDEX idx_stg_atend_cid ON stg_atendimento(co_fat_cidadao_pec);CREATE INDEX idx_stg_atend_dt ON stg_atendimento(dt_registro);CREATE INDEX idx_stg_atend_classif ON stg_atendimento(atend_ind_classificacao);CREATE INDEX idx_stg_proc_cid ON stg_procedimentos(co_fat_cidadao_pec);CREATE INDEX idx_stg_proc_dt ON stg_procedimentos(dt_registro);CREATE INDEX idx_stg_proc_coproc ON stg_procedimentos(co_proced);CREATE INDEX idx_stg_cid_cid ON stg_cidadao(co_fat_cidadao_pec);